#include <stdio.h>
#define SIZE 3

typedef struct {
    int data[SIZE];
    int front;
    int rear;
} Queue;

void enq(Queue *q, int v){
    q->data[q->rear]=v;
    q->rear=(q->rear+1)%SIZE;
}

int deq(Queue *q){
    int v=q->data[q->front];
    q->front=(q->front+1)%SIZE;
    return v;
}

int main(void){
    Queue q={{0},0,0};
    enq(&q,1);
    enq(&q,2);
    deq(&q);
    enq(&q,3);

    int first=deq(&q);
    int second=deq(&q);
    printf("%d 그리고 %d",first,second);
    return 0;
}

